/**
 * Stick-figure illustrations generated by tools/exercise-figures (run `node tools/exercise-figures/build.mjs`).
 * Only exercises listed here have a figure; the rest show text only.
 */
export const exerciseFigureIds = new Set<string>([
  'barbell-bench-press',
  'barbell-squat',
  'romanian-deadlift',
  'lat-pulldown',
  'barbell-curl',
]);

/**
 * AI-generated realistic photos (public/exercise-photos). Only exercises whose BOTH states passed
 * visual review are listed here; the rest keep the SVG illustration.
 */
export const exercisePhotoIds = new Set<string>([
  'romanian-deadlift',
  'lat-pulldown',
  'lateral-raise',
  'shoulder-press',
  'one-arm-dumbbell-row',
  'bulgarian-split-squat',
  'leg-press',
  'cable-crunch',
  'machine-chest-press',
  'cable-triceps-pushdown',
  'seated-cable-row',
  'barbell-bench-press',
  'barbell-squat',
  'barbell-curl',
  'cable-fly',
  'face-pull',
  'incline-dumbbell-press',
  'cable-lateral-raise',
  'hammer-curl',
  'cable-curl',
  'incline-barbell-press',
  'leg-extension',
  'machine-row',
  'neutral-grip-lat-pulldown',
  'leg-curl',
  'dumbbell-biceps-curl',
  'incline-dumbbell-curl',
  'overhead-cable-triceps-extension',
]);

/** True when the exercise has either a photo pair or an SVG pair. */
export function hasExerciseFigure(exerciseId: string): boolean {
  return exerciseFigureIds.has(exerciseId) || exercisePhotoIds.has(exerciseId);
}

export type FigureState = 'start' | 'main';

export function exerciseFigureSrc(exerciseId: string, state: FigureState): string {
  const base = import.meta.env.BASE_URL;
  return exercisePhotoIds.has(exerciseId)
    ? `${base}exercise-photos/${exerciseId}-${state}.jpg`
    : `${base}exercise-images/${exerciseId}-${state}.svg`;
}
